-- PlayCrows V2 Event005: MY PLAYCROWS V2 JOURNEY
-- Cloned from the V1 Event004 structure, adapted for V2 and expanded with the requested rewards.
-- Idempotent: updates an existing V2 Event005 if present, otherwise inserts it.

do $$
declare
  v_event_id uuid;
begin
  select id into v_event_id
  from public.events
  where server = 'v2'
    and regexp_replace(event_number, '^0+', '') = '5'
  order by created_at desc
  limit 1;

  if v_event_id is null then
    insert into public.events (
      server, slug, event_number, title, short_description, description,
      mechanics, rewards, form_fields, translations, action_links,
      status, starts_at, ends_at, published_at,
      claim_frequency, weekly_reset_day, weekly_reset_hour, weekly_reset_timezone,
      require_character_name, require_player_id, created_at, updated_at
    ) values (
      'v2', 'event-005', '005', $title$🎉 MY PLAYCROWS V2 JOURNEY$title$, $short$You’ve reached Level 60 — now it’s time to show the community what your PlayCrows V2 journey has been like!$short$, $desc$Share your progression, memorable gameplay moments, and the PlayCrows V2 features you’ve enjoyed along the way. Show other players where you started, how far you’ve progressed, and the memorable moments you’ve experienced in PlayCrows V2.$desc$,
      $mechanics$["Create content showcasing your PlayCrows V2 Journey. You may post screenshots, a short video, or both on Facebook, TikTok, or Instagram.","Show the game features, systems, or PlayCrows V2 content that you enjoy.","Show your character progression and how your character has become stronger throughout your journey.","Share your lucky Mythic Mount or Mythic Weapon Style pulls and show how achievable they can be in PlayCrows V2.","Share memorable Boss Raid battles, victories, drops, or moments with your party or guild.","Include a short description about your PlayCrows V2 experience and what you enjoy about the game.","Minimum level requirement: your character must be Level 60 or above to participate.","Your original post must include the PlayCrows V2 Discord invite link.","If posting on Facebook, tag the Official PlayCrows V2 Facebook Page.","Share or promote your content in 5 different active gaming communities, preferably related to Night Crows or MMORPGs.","All 5 communities must be active and legitimate. Inactive, abandoned, spam, irrelevant, or event-only groups will not be accepted.","Your original content and all community posts must remain publicly visible and accessible for verification.","Private, inaccessible, deleted, duplicate, inactive-community, or invalid submissions will not be accepted."]$mechanics$::jsonb,
      $rewards$["Draught of Vigilance (Bound) ×200","Superior Draught of Fury (Bound) ×20","Superior Draught of Overcoming (Bound) ×20","Superior Draught of Antagonism (Bound) ×20","sealed Hero Weapon Selection Box (Attribution) ×1","sealed Hero Accessory Selection Box (Attribution) ×1","sealed Hero Armor Selection Box (Attribution) ×6","sealed Hero Bracelet selection box (attribution) ×1","sealed Hero Epaulettes Selection Box (Attribution) ×1","sealed Hero Trinket Selection Box (Attribution) ×5","sturdy bundle of yarn box (attributed) ×10","torn of invoices (attribution) ×50","torn seniority letter (attribution) ×50"]$rewards$::jsonb,
      $fields$[{"id":"field_en_1786794917915","type":"url","label":"Original PlayCrows V2 Journey Post","helpText":"Enter the direct link to your public Facebook, TikTok, or Instagram PlayCrows V2 Journey post.","maxItems":3,"minItems":3,"required":true,"placeholder":"https://…"},{"id":"field_en_1786794946905","type":"links","label":"Active Gaming Community Links","helpText":"Submit the 5 links where you promoted your PlayCrows V2 Journey. All communities must be active.","maxItems":5,"minItems":5,"required":true,"placeholder":"https://…"}]$fields$::jsonb,
      $translations${"ko":{"title":"🎉나의 PLAYCROWS V2 여정","rewards":["경계의 영약 (귀속) ×200","상급 분노의 영약 (귀속) ×20","상급 극복의 영약 (귀속) ×20","상급 적대의 영약 (귀속) ×20","봉인된 영웅 무기 선택 상자 (귀속) ×1","봉인된 영웅 장신구 선택 상자 (귀속) ×1","봉인된 영웅 방어구 선택 상자 (귀속) ×6","봉인된 영웅 팔찌 선택 상자 (귀속) ×1","봉인된 영웅 견갑 선택 상자 (귀속) ×1","봉인된 영웅 보조 장비 선택 상자 (귀속) ×5","sturdy bundle of yarn box (attributed) ×10","torn of invoices (attribution) ×50","torn seniority letter (attribution) ×50"],"mechanics":["자신의 PlayCrows V2 플레이 여정을 소개하는 콘텐츠를 만들어 주세요. 스크린샷, 짧은 영상 또는 두 가지를 함께 사용할 수 있습니다.","PlayCrows V2에서 즐기고 있는 게임 콘텐츠, 시스템 또는 특징을 소개해 주세요.","자신의 캐릭터가 어떻게 성장하고 강해졌는지 성장 과정을 보여주세요.","신화 탈것 또는 신화 무기 외형을 획득한 행운의 순간과 PlayCrows V2에서 얼마나 획득하기 좋은지 보여주세요.","파티 또는 길드원들과 함께한 보스 레이드 전투, 승리, 보상 획득 또는 기억에 남는 순간을 공유해 주세요.","PlayCrows V2를 플레이하면서 느낀 점이나 게임에서 마음에 드는 부분을 간단하게 작성해 주세요.","본 이벤트는 레벨 60 이상의 캐릭터만 참여할 수 있습니다.","홍보 게시물에는 PlayCrows V2 Discord 초대 링크를 반드시 포함해 주세요.","작성한 PlayCrows V2 Journey 콘텐츠를 서로 다른 8개의 한국 게임 광고/홍보 사이트에 게시해 주세요.","반드시 서로 다른 8개의 사이트를 이용해야 하며, 동일한 사이트에 여러 번 게시한 경우 1개의 사이트로만 인정됩니다.","모든 사이트는 실제로 운영되고 있는 활성화된 게임 광고/홍보 사이트여야 합니다.","모든 홍보 게시물은 운영진이 확인할 수 있도록 공개 상태로 유지되어야 합니다.","중복 사이트, 비공개 또는 삭제된 게시물, 접속할 수 없는 링크, 스팸성 게시물, 비활성 사이트 또는 유효하지 않은 게시물은 인정되지 않습니다."],"description":"캐릭터의 성장 과정, 기억에 남는 플레이 순간, 그리고 PlayCrows V2에서 즐긴 다양한 콘텐츠를 공유해 주세요. 처음 시작했던 순간부터 지금까지 얼마나 성장했는지 여러분의 PlayCrows V2 여정을 보여주세요.","form_fields":[{"id":"field_en_1786794917915","type":"links","label":"홍보 게시물 링크","helpText":"서로 다른 8개의 활성화된 한국 게임 광고/홍보 사이트에 게시한 링크를 제출해 주세요.","maxItems":8,"minItems":8,"required":true,"placeholder":"https://…"}],"action_links":[],"require_player_id":true,"short_description":"레벨 60을 달성하셨나요? 이제 여러분의 PlayCrows V2 여정을 다른 플레이어들에게 보여주세요!","require_character_name":true},"pt":{"title":"🎉MINHA JORNADA NO PLAYCROWS V2","rewards":["Draught of Vigilance (Bound) ×200","Superior Draught of Fury (Bound) ×20","Superior Draught of Overcoming (Bound) ×20","Superior Draught of Antagonism (Bound) ×20","Sealed Hero Weapon Selection Box (Attribution) ×1","Sealed Hero Accessory Selection Box (Attribution) ×1","Sealed Hero Armor Selection Box (Attribution) ×6","Sealed Hero Bracelet Selection Box (Attribution) ×1","Sealed Hero Epaulettes Selection Box (Attribution) ×1","Sealed Hero Trinket Selection Box (Attribution) ×5","sturdy bundle of yarn box (attributed) ×10","torn of invoices (attribution) ×50","torn seniority letter (attribution) ×50"],"mechanics":["Crie um conteúdo mostrando sua Jornada no PlayCrows V2. Você pode publicar capturas de tela, um vídeo curto ou ambos no Facebook, TikTok ou Instagram.","Mostre recursos, sistemas ou conteúdos do PlayCrows V2 que você mais gosta.","Mostre a progressão do seu personagem e como ele ficou mais forte durante sua jornada.","Compartilhe seus momentos de sorte ao conseguir uma Mythic Mount ou Mythic Weapon Style e mostre como elas podem ser obtidas no PlayCrows V2.","Compartilhe batalhas, vitórias, drops ou momentos memoráveis em Boss Raids com seu grupo ou guilda.","Inclua uma breve descrição da sua experiência e do que você gosta no PlayCrows V2.","Seu personagem deve estar no Nível 60 ou superior.","Sua publicação original deve incluir o link de convite do Discord do PlayCrows V2.","Se publicar no Facebook, marque a página oficial do PlayCrows V2.","Compartilhe ou promova seu conteúdo em 5 comunidades de jogos diferentes e ativas, preferencialmente relacionadas a Night Crows ou MMORPGs.","Todas as 5 comunidades devem ser ativas e legítimas. Grupos inativos, abandonados, de spam, irrelevantes ou criados apenas para o evento não serão aceitos.","Sua publicação original e todas as publicações nas comunidades devem permanecer públicas e acessíveis para verificação.","Publicações privadas, links inacessíveis, conteúdo excluído, comunidades duplicadas ou inativas e inscrições inválidas não serão aceitos."],"description":"Compartilhe sua progressão, seus momentos mais marcantes e os recursos do PlayCrows V2 que você mais gosta. Mostre onde sua jornada começou, o quanto seu personagem evoluiu e suas melhores experiências no jogo.","form_fields":[{"id":"field_en_1786794917915","type":"url","label":"Link da publicação PlayCrows V2 Journey","helpText":"Enter the direct link to your public Facebook, TikTok, or Instagram PlayCrows V2 Journey post.","maxItems":3,"minItems":3,"required":true,"placeholder":"https://…"},{"id":"field_en_1786794946905","type":"links","label":"Links das comunidades de jogos ativas","helpText":"Submit the 5 links where you promoted your PlayCrows V2 Journey. All communities must be active.","maxItems":5,"minItems":5,"required":true,"placeholder":"https://…"}],"action_links":[],"require_player_id":true,"short_description":"Você alcançou o Nível 60 — agora é hora de mostrar à comunidade como tem sido a sua jornada no PlayCrows V2!","require_character_name":true},"ru":{"title":"🎉МОЙ ПУТЬ В PLAYCROWS V2","rewards":["Draught of Vigilance (Bound) ×200","Superior Draught of Fury (Bound) ×20","Superior Draught of Overcoming (Bound) ×20","Superior Draught of Antagonism (Bound) ×20","Sealed Hero Weapon Selection Box (Attribution) ×1","Sealed Hero Accessory Selection Box (Attribution) ×1","Sealed Hero Armor Selection Box (Attribution) ×6","Sealed Hero Bracelet Selection Box (Attribution) ×1","Sealed Hero Epaulettes Selection Box (Attribution) ×1","Sealed Hero Trinket Selection Box (Attribution) ×5","sturdy bundle of yarn box (attributed) ×10","torn of invoices (attribution) ×50","torn seniority letter (attribution) ×50"],"mechanics":["🔹 Создайте публикацию о своём PlayCrows V2 Journey. Вы можете использовать скриншоты, короткое видео или их комбинацию и опубликовать материал в VK, Telegram или Instagram.","🔹 Покажите интересные функции, системы или контент PlayCrows V2, которые вам нравятся.","🔹 Продемонстрируйте развитие своего персонажа и то, как он становился сильнее.","🔹 Поделитесь удачными моментами получения Mythic Mount или Mythic Weapon Style и покажите возможности их получения в PlayCrows V2.","🔹 Покажите сражения с боссами, победы, полученные награды или запоминающиеся моменты Boss Raid вместе с группой или гильдией.","🔹 Добавьте небольшое описание своего опыта и расскажите, что вам нравится в PlayCrows V2.","🔹 Для участия ваш персонаж должен быть 60-го уровня или выше.","🔹 В оригинальной публикации обязательно должна присутствовать ссылка-приглашение в Discord PlayCrows V2.","🔹 Поделитесь или продвигайте свою публикацию как минимум в 5 разных активных игровых сообществах, группах или каналах в VK, Telegram или Instagram.","🔹 Все 5 публикаций могут быть размещены на одной платформе, но обязательно в 5 разных сообществах, группах или каналах. Предпочтительно выбирать сообщества, связанные с Night Crows или MMORPG.","🔹 Все 5 сообществ должны быть реальными и активными. Неактивные, заброшенные, спам-сообщества, нерелевантные группы или сообщества, созданные исключительно для участия в событии, не принимаются.","🔹 Оригинальная публикация и все 5 рекламных публикаций должны оставаться публичными и доступными для проверки.","🔹 Приватные или удалённые публикации, недоступные ссылки, повторяющиеся или неактивные сообщества, а также недействительные заявки не принимаются."],"description":"Поделитесь развитием своего персонажа, запоминающимися игровыми моментами и контентом PlayCrows V2, который вам нравится больше всего. Покажите другим игрокам, с чего вы начинали и чего достигли.","form_fields":[{"id":"field_en_1786794917915","type":"url","label":"Ссылка на публикацию PlayCrows V2 Journey","helpText":"Enter the direct link to your public Facebook, TikTok, or Instagram PlayCrows V2 Journey post.","maxItems":3,"minItems":3,"required":true,"placeholder":"https://…"},{"id":"field_en_1786794946905","type":"links","label":"Ссылки на активные игровые сообщества","helpText":"Submit the 5 links where you promoted your PlayCrows V2 Journey. All communities must be active.","maxItems":5,"minItems":5,"required":true,"placeholder":"https://…"}],"action_links":[],"require_player_id":true,"short_description":"Вы достигли 60 уровня — теперь пришло время показать сообществу свой путь в PlayCrows V2!","require_character_name":true},"th":{"title":"🎉เส้นทาง PLAYCROWS V2 ของฉัน","rewards":["Draught of Vigilance (Bound) ×200","Superior Draught of Fury (Bound) ×20","Superior Draught of Overcoming (Bound) ×20","Superior Draught of Antagonism (Bound) ×20","Sealed Hero Weapon Selection Box (Attribution) ×1","Sealed Hero Accessory Selection Box (Attribution) ×1","Sealed Hero Armor Selection Box (Attribution) ×6","Sealed Hero Bracelet Selection Box (Attribution) ×1","Sealed Hero Epaulettes Selection Box (Attribution) ×1","Sealed Hero Trinket Selection Box (Attribution) ×5","sturdy bundle of yarn box (attributed) ×10","torn of invoices (attribution) ×50","torn seniority letter (attribution) ×50"],"mechanics":["สร้างคอนเทนต์เกี่ยวกับ PlayCrows V2 Journey ของคุณ โดยสามารถโพสต์ภาพหน้าจอ วิดีโอสั้น หรือทั้งสองอย่างบน Facebook, TikTok หรือ Instagram","แสดงฟีเจอร์ ระบบ หรือคอนเทนต์ของ PlayCrows V2 ที่คุณชื่นชอบ","แสดงพัฒนาการของตัวละครและการเติบโตที่ทำให้ตัวละครของคุณแข็งแกร่งขึ้น","แบ่งปันช่วงเวลาโชคดีที่ได้รับ Mythic Mount หรือ Mythic Weapon Style และแสดงให้เห็นว่าสามารถได้รับใน PlayCrows V2","แบ่งปันช่วงเวลา Boss Raid การต่อสู้ ชัยชนะ ของรางวัล หรือความทรงจำกับปาร์ตี้หรือกิลด์","เขียนคำอธิบายสั้น ๆ เกี่ยวกับประสบการณ์และสิ่งที่คุณชื่นชอบใน PlayCrows V2","ตัวละครของคุณต้องมีเลเวล 60 ขึ้นไป","โพสต์ต้นฉบับต้องมีลิงก์เชิญ Discord ของ PlayCrows V2","หากโพสต์บน Facebook กรุณาแท็กเพจ Facebook อย่างเป็นทางการของ PlayCrows V2","แชร์หรือโปรโมตคอนเทนต์ใน 5 ชุมชนเกมที่แตกต่างกันและยังมีความเคลื่อนไหว โดยแนะนำชุมชน Night Crows หรือ MMORPG","ทั้ง 5 ชุมชนต้องเป็นชุมชนที่มีการใช้งานจริง กลุ่มที่ไม่มีความเคลื่อนไหว เป็นสแปม ไม่เกี่ยวข้อง หรือสร้างขึ้นเพื่อกิจกรรมจะไม่ได้รับการยอมรับ","โพสต์ต้นฉบับและโพสต์ในชุมชนทั้งหมดต้องเป็นสาธารณะและสามารถเข้าถึงได้","โพสต์ส่วนตัว ลิงก์ที่เข้าถึงไม่ได้ โพสต์ที่ถูกลบ ชุมชนซ้ำหรือไม่มีความเคลื่อนไหว และการส่งที่ไม่ถูกต้องจะไม่ได้รับการยอมรับ"],"description":"แบ่งปันพัฒนาการของตัวละคร ช่วงเวลาที่น่าจดจำ และฟีเจอร์ต่าง ๆ ของ PlayCrows V2 ที่คุณชื่นชอบ แสดงให้ผู้เล่นคนอื่นเห็นว่าคุณเริ่มต้นจากจุดไหนและเดินทางมาไกลแค่ไหนแล้ว","form_fields":[{"id":"field_en_1786794917915","type":"url","label":"ลิงก์โพสต์ PlayCrows V2 Journey","helpText":"Enter the direct link to your public Facebook, TikTok, or Instagram PlayCrows V2 Journey post.","maxItems":3,"minItems":3,"required":true,"placeholder":"https://…"},{"id":"field_en_1786794946905","type":"links","label":"ลิงก์ชุมชนเกมที่ใช้งานอยู่","helpText":"Submit the 5 links where you promoted your PlayCrows V2 Journey. All communities must be active.","maxItems":5,"minItems":5,"required":true,"placeholder":"https://…"}],"action_links":[],"require_player_id":true,"short_description":"คุณมาถึงเลเวล 60 แล้ว — ถึงเวลาที่จะแบ่งปันเส้นทาง PlayCrows V2 ของคุณให้กับชุมชน!","require_character_name":true},"zh-TW":{"title":"🎉我的 PLAYCROWS V2 旅程","rewards":["Draught of Vigilance (Bound) ×200","Superior Draught of Fury (Bound) ×20","Superior Draught of Overcoming (Bound) ×20","Superior Draught of Antagonism (Bound) ×20","Sealed Hero Weapon Selection Box (Attribution) ×1","Sealed Hero Accessory Selection Box (Attribution) ×1","Sealed Hero Armor Selection Box (Attribution) ×6","Sealed Hero Bracelet Selection Box (Attribution) ×1","Sealed Hero Epaulettes Selection Box (Attribution) ×1","Sealed Hero Trinket Selection Box (Attribution) ×5","sturdy bundle of yarn box (attributed) ×10","torn of invoices (attribution) ×50","torn seniority letter (attribution) ×50"],"mechanics":["製作介紹你的 PlayCrows V2 Journey 的內容。你可以在 Facebook、TikTok 或 Instagram 發布遊戲截圖、短影片，或兩者一起分享。","分享你喜歡的 PlayCrows V2 遊戲特色、系統或內容。","展示你的角色成長過程以及角色如何逐漸變得更強。","分享你幸運獲得神話坐騎或神話武器外觀的精彩時刻，並展示在 PlayCrows V2 中獲得它們的機會。","分享與隊伍或公會一起挑戰 Boss Raid 的戰鬥、勝利、掉落或其他難忘時刻。","簡單描述你的 PlayCrows V2 遊戲體驗以及你喜歡遊戲的原因。","角色必須達到 60 級或以上才能參加。","原始貼文中必須清楚包含 PlayCrows V2 Discord 邀請連結。","如果使用 Facebook 發布，請標記 PlayCrows V2 官方 Facebook 專頁。","將你的內容分享到 5 個不同且活躍的遊戲社群，建議選擇與 Night Crows 或 MMORPG 相關的社群。","5 個社群都必須是真實且活躍的社群。不活躍、已廢棄、垃圾廣告、無關或專門為活動建立的社群將不被接受。","原始內容以及所有社群貼文必須保持公開且可正常瀏覽，以便工作人員驗證。","私人貼文、無法瀏覽或已刪除的內容、重複或不活躍的社群，以及無效的提交將不被接受。"],"description":"分享你的角色成長、難忘的遊戲時刻，以及你最喜歡的 PlayCrows V2 遊戲內容。向其他玩家展示你從哪裡開始、角色成長了多少，以及你在 PlayCrows V2 中最精彩的經歷。","form_fields":[{"id":"field_en_1786794917915","type":"url","label":"PlayCrows V2 Journey 原始貼文連結","helpText":"Enter the direct link to your public Facebook, TikTok, or Instagram PlayCrows V2 Journey post.","maxItems":3,"minItems":3,"required":true,"placeholder":"https://…"},{"id":"field_en_1786794946905","type":"links","label":"活躍遊戲社群連結","helpText":"Submit the 5 links where you promoted your PlayCrows V2 Journey. All communities must be active.","maxItems":5,"minItems":5,"required":true,"placeholder":"https://…"}],"action_links":[],"require_player_id":true,"short_description":"你已經達到 60 級 — 現在是時候向大家分享你的 PlayCrows V2 冒險旅程了！","require_character_name":true}}$translations$::jsonb,
      '[]'::jsonb,
      'active', now(), null, now(),
      'once', 1, 4, 'Asia/Manila',
      true, true, now(), now()
    );
  else
    update public.events
    set
      slug = 'event-005',
      event_number = '005',
      title = $title2$🎉 MY PLAYCROWS V2 JOURNEY$title2$,
      short_description = $short2$You’ve reached Level 60 — now it’s time to show the community what your PlayCrows V2 journey has been like!$short2$,
      description = $desc2$Share your progression, memorable gameplay moments, and the PlayCrows V2 features you’ve enjoyed along the way. Show other players where you started, how far you’ve progressed, and the memorable moments you’ve experienced in PlayCrows V2.$desc2$,
      mechanics = $mechanics2$["Create content showcasing your PlayCrows V2 Journey. You may post screenshots, a short video, or both on Facebook, TikTok, or Instagram.","Show the game features, systems, or PlayCrows V2 content that you enjoy.","Show your character progression and how your character has become stronger throughout your journey.","Share your lucky Mythic Mount or Mythic Weapon Style pulls and show how achievable they can be in PlayCrows V2.","Share memorable Boss Raid battles, victories, drops, or moments with your party or guild.","Include a short description about your PlayCrows V2 experience and what you enjoy about the game.","Minimum level requirement: your character must be Level 60 or above to participate.","Your original post must include the PlayCrows V2 Discord invite link.","If posting on Facebook, tag the Official PlayCrows V2 Facebook Page.","Share or promote your content in 5 different active gaming communities, preferably related to Night Crows or MMORPGs.","All 5 communities must be active and legitimate. Inactive, abandoned, spam, irrelevant, or event-only groups will not be accepted.","Your original content and all community posts must remain publicly visible and accessible for verification.","Private, inaccessible, deleted, duplicate, inactive-community, or invalid submissions will not be accepted."]$mechanics2$::jsonb,
      rewards = $rewards2$["Draught of Vigilance (Bound) ×200","Superior Draught of Fury (Bound) ×20","Superior Draught of Overcoming (Bound) ×20","Superior Draught of Antagonism (Bound) ×20","sealed Hero Weapon Selection Box (Attribution) ×1","sealed Hero Accessory Selection Box (Attribution) ×1","sealed Hero Armor Selection Box (Attribution) ×6","sealed Hero Bracelet selection box (attribution) ×1","sealed Hero Epaulettes Selection Box (Attribution) ×1","sealed Hero Trinket Selection Box (Attribution) ×5","sturdy bundle of yarn box (attributed) ×10","torn of invoices (attribution) ×50","torn seniority letter (attribution) ×50"]$rewards2$::jsonb,
      form_fields = $fields2$[{"id":"field_en_1786794917915","type":"url","label":"Original PlayCrows V2 Journey Post","helpText":"Enter the direct link to your public Facebook, TikTok, or Instagram PlayCrows V2 Journey post.","maxItems":3,"minItems":3,"required":true,"placeholder":"https://…"},{"id":"field_en_1786794946905","type":"links","label":"Active Gaming Community Links","helpText":"Submit the 5 links where you promoted your PlayCrows V2 Journey. All communities must be active.","maxItems":5,"minItems":5,"required":true,"placeholder":"https://…"}]$fields2$::jsonb,
      translations = $translations2${"ko":{"title":"🎉나의 PLAYCROWS V2 여정","rewards":["경계의 영약 (귀속) ×200","상급 분노의 영약 (귀속) ×20","상급 극복의 영약 (귀속) ×20","상급 적대의 영약 (귀속) ×20","봉인된 영웅 무기 선택 상자 (귀속) ×1","봉인된 영웅 장신구 선택 상자 (귀속) ×1","봉인된 영웅 방어구 선택 상자 (귀속) ×6","봉인된 영웅 팔찌 선택 상자 (귀속) ×1","봉인된 영웅 견갑 선택 상자 (귀속) ×1","봉인된 영웅 보조 장비 선택 상자 (귀속) ×5","sturdy bundle of yarn box (attributed) ×10","torn of invoices (attribution) ×50","torn seniority letter (attribution) ×50"],"mechanics":["자신의 PlayCrows V2 플레이 여정을 소개하는 콘텐츠를 만들어 주세요. 스크린샷, 짧은 영상 또는 두 가지를 함께 사용할 수 있습니다.","PlayCrows V2에서 즐기고 있는 게임 콘텐츠, 시스템 또는 특징을 소개해 주세요.","자신의 캐릭터가 어떻게 성장하고 강해졌는지 성장 과정을 보여주세요.","신화 탈것 또는 신화 무기 외형을 획득한 행운의 순간과 PlayCrows V2에서 얼마나 획득하기 좋은지 보여주세요.","파티 또는 길드원들과 함께한 보스 레이드 전투, 승리, 보상 획득 또는 기억에 남는 순간을 공유해 주세요.","PlayCrows V2를 플레이하면서 느낀 점이나 게임에서 마음에 드는 부분을 간단하게 작성해 주세요.","본 이벤트는 레벨 60 이상의 캐릭터만 참여할 수 있습니다.","홍보 게시물에는 PlayCrows V2 Discord 초대 링크를 반드시 포함해 주세요.","작성한 PlayCrows V2 Journey 콘텐츠를 서로 다른 8개의 한국 게임 광고/홍보 사이트에 게시해 주세요.","반드시 서로 다른 8개의 사이트를 이용해야 하며, 동일한 사이트에 여러 번 게시한 경우 1개의 사이트로만 인정됩니다.","모든 사이트는 실제로 운영되고 있는 활성화된 게임 광고/홍보 사이트여야 합니다.","모든 홍보 게시물은 운영진이 확인할 수 있도록 공개 상태로 유지되어야 합니다.","중복 사이트, 비공개 또는 삭제된 게시물, 접속할 수 없는 링크, 스팸성 게시물, 비활성 사이트 또는 유효하지 않은 게시물은 인정되지 않습니다."],"description":"캐릭터의 성장 과정, 기억에 남는 플레이 순간, 그리고 PlayCrows V2에서 즐긴 다양한 콘텐츠를 공유해 주세요. 처음 시작했던 순간부터 지금까지 얼마나 성장했는지 여러분의 PlayCrows V2 여정을 보여주세요.","form_fields":[{"id":"field_en_1786794917915","type":"links","label":"홍보 게시물 링크","helpText":"서로 다른 8개의 활성화된 한국 게임 광고/홍보 사이트에 게시한 링크를 제출해 주세요.","maxItems":8,"minItems":8,"required":true,"placeholder":"https://…"}],"action_links":[],"require_player_id":true,"short_description":"레벨 60을 달성하셨나요? 이제 여러분의 PlayCrows V2 여정을 다른 플레이어들에게 보여주세요!","require_character_name":true},"pt":{"title":"🎉MINHA JORNADA NO PLAYCROWS V2","rewards":["Draught of Vigilance (Bound) ×200","Superior Draught of Fury (Bound) ×20","Superior Draught of Overcoming (Bound) ×20","Superior Draught of Antagonism (Bound) ×20","Sealed Hero Weapon Selection Box (Attribution) ×1","Sealed Hero Accessory Selection Box (Attribution) ×1","Sealed Hero Armor Selection Box (Attribution) ×6","Sealed Hero Bracelet Selection Box (Attribution) ×1","Sealed Hero Epaulettes Selection Box (Attribution) ×1","Sealed Hero Trinket Selection Box (Attribution) ×5","sturdy bundle of yarn box (attributed) ×10","torn of invoices (attribution) ×50","torn seniority letter (attribution) ×50"],"mechanics":["Crie um conteúdo mostrando sua Jornada no PlayCrows V2. Você pode publicar capturas de tela, um vídeo curto ou ambos no Facebook, TikTok ou Instagram.","Mostre recursos, sistemas ou conteúdos do PlayCrows V2 que você mais gosta.","Mostre a progressão do seu personagem e como ele ficou mais forte durante sua jornada.","Compartilhe seus momentos de sorte ao conseguir uma Mythic Mount ou Mythic Weapon Style e mostre como elas podem ser obtidas no PlayCrows V2.","Compartilhe batalhas, vitórias, drops ou momentos memoráveis em Boss Raids com seu grupo ou guilda.","Inclua uma breve descrição da sua experiência e do que você gosta no PlayCrows V2.","Seu personagem deve estar no Nível 60 ou superior.","Sua publicação original deve incluir o link de convite do Discord do PlayCrows V2.","Se publicar no Facebook, marque a página oficial do PlayCrows V2.","Compartilhe ou promova seu conteúdo em 5 comunidades de jogos diferentes e ativas, preferencialmente relacionadas a Night Crows ou MMORPGs.","Todas as 5 comunidades devem ser ativas e legítimas. Grupos inativos, abandonados, de spam, irrelevantes ou criados apenas para o evento não serão aceitos.","Sua publicação original e todas as publicações nas comunidades devem permanecer públicas e acessíveis para verificação.","Publicações privadas, links inacessíveis, conteúdo excluído, comunidades duplicadas ou inativas e inscrições inválidas não serão aceitos."],"description":"Compartilhe sua progressão, seus momentos mais marcantes e os recursos do PlayCrows V2 que você mais gosta. Mostre onde sua jornada começou, o quanto seu personagem evoluiu e suas melhores experiências no jogo.","form_fields":[{"id":"field_en_1786794917915","type":"url","label":"Link da publicação PlayCrows V2 Journey","helpText":"Enter the direct link to your public Facebook, TikTok, or Instagram PlayCrows V2 Journey post.","maxItems":3,"minItems":3,"required":true,"placeholder":"https://…"},{"id":"field_en_1786794946905","type":"links","label":"Links das comunidades de jogos ativas","helpText":"Submit the 5 links where you promoted your PlayCrows V2 Journey. All communities must be active.","maxItems":5,"minItems":5,"required":true,"placeholder":"https://…"}],"action_links":[],"require_player_id":true,"short_description":"Você alcançou o Nível 60 — agora é hora de mostrar à comunidade como tem sido a sua jornada no PlayCrows V2!","require_character_name":true},"ru":{"title":"🎉МОЙ ПУТЬ В PLAYCROWS V2","rewards":["Draught of Vigilance (Bound) ×200","Superior Draught of Fury (Bound) ×20","Superior Draught of Overcoming (Bound) ×20","Superior Draught of Antagonism (Bound) ×20","Sealed Hero Weapon Selection Box (Attribution) ×1","Sealed Hero Accessory Selection Box (Attribution) ×1","Sealed Hero Armor Selection Box (Attribution) ×6","Sealed Hero Bracelet Selection Box (Attribution) ×1","Sealed Hero Epaulettes Selection Box (Attribution) ×1","Sealed Hero Trinket Selection Box (Attribution) ×5","sturdy bundle of yarn box (attributed) ×10","torn of invoices (attribution) ×50","torn seniority letter (attribution) ×50"],"mechanics":["🔹 Создайте публикацию о своём PlayCrows V2 Journey. Вы можете использовать скриншоты, короткое видео или их комбинацию и опубликовать материал в VK, Telegram или Instagram.","🔹 Покажите интересные функции, системы или контент PlayCrows V2, которые вам нравятся.","🔹 Продемонстрируйте развитие своего персонажа и то, как он становился сильнее.","🔹 Поделитесь удачными моментами получения Mythic Mount или Mythic Weapon Style и покажите возможности их получения в PlayCrows V2.","🔹 Покажите сражения с боссами, победы, полученные награды или запоминающиеся моменты Boss Raid вместе с группой или гильдией.","🔹 Добавьте небольшое описание своего опыта и расскажите, что вам нравится в PlayCrows V2.","🔹 Для участия ваш персонаж должен быть 60-го уровня или выше.","🔹 В оригинальной публикации обязательно должна присутствовать ссылка-приглашение в Discord PlayCrows V2.","🔹 Поделитесь или продвигайте свою публикацию как минимум в 5 разных активных игровых сообществах, группах или каналах в VK, Telegram или Instagram.","🔹 Все 5 публикаций могут быть размещены на одной платформе, но обязательно в 5 разных сообществах, группах или каналах. Предпочтительно выбирать сообщества, связанные с Night Crows или MMORPG.","🔹 Все 5 сообществ должны быть реальными и активными. Неактивные, заброшенные, спам-сообщества, нерелевантные группы или сообщества, созданные исключительно для участия в событии, не принимаются.","🔹 Оригинальная публикация и все 5 рекламных публикаций должны оставаться публичными и доступными для проверки.","🔹 Приватные или удалённые публикации, недоступные ссылки, повторяющиеся или неактивные сообщества, а также недействительные заявки не принимаются."],"description":"Поделитесь развитием своего персонажа, запоминающимися игровыми моментами и контентом PlayCrows V2, который вам нравится больше всего. Покажите другим игрокам, с чего вы начинали и чего достигли.","form_fields":[{"id":"field_en_1786794917915","type":"url","label":"Ссылка на публикацию PlayCrows V2 Journey","helpText":"Enter the direct link to your public Facebook, TikTok, or Instagram PlayCrows V2 Journey post.","maxItems":3,"minItems":3,"required":true,"placeholder":"https://…"},{"id":"field_en_1786794946905","type":"links","label":"Ссылки на активные игровые сообщества","helpText":"Submit the 5 links where you promoted your PlayCrows V2 Journey. All communities must be active.","maxItems":5,"minItems":5,"required":true,"placeholder":"https://…"}],"action_links":[],"require_player_id":true,"short_description":"Вы достигли 60 уровня — теперь пришло время показать сообществу свой путь в PlayCrows V2!","require_character_name":true},"th":{"title":"🎉เส้นทาง PLAYCROWS V2 ของฉัน","rewards":["Draught of Vigilance (Bound) ×200","Superior Draught of Fury (Bound) ×20","Superior Draught of Overcoming (Bound) ×20","Superior Draught of Antagonism (Bound) ×20","Sealed Hero Weapon Selection Box (Attribution) ×1","Sealed Hero Accessory Selection Box (Attribution) ×1","Sealed Hero Armor Selection Box (Attribution) ×6","Sealed Hero Bracelet Selection Box (Attribution) ×1","Sealed Hero Epaulettes Selection Box (Attribution) ×1","Sealed Hero Trinket Selection Box (Attribution) ×5","sturdy bundle of yarn box (attributed) ×10","torn of invoices (attribution) ×50","torn seniority letter (attribution) ×50"],"mechanics":["สร้างคอนเทนต์เกี่ยวกับ PlayCrows V2 Journey ของคุณ โดยสามารถโพสต์ภาพหน้าจอ วิดีโอสั้น หรือทั้งสองอย่างบน Facebook, TikTok หรือ Instagram","แสดงฟีเจอร์ ระบบ หรือคอนเทนต์ของ PlayCrows V2 ที่คุณชื่นชอบ","แสดงพัฒนาการของตัวละครและการเติบโตที่ทำให้ตัวละครของคุณแข็งแกร่งขึ้น","แบ่งปันช่วงเวลาโชคดีที่ได้รับ Mythic Mount หรือ Mythic Weapon Style และแสดงให้เห็นว่าสามารถได้รับใน PlayCrows V2","แบ่งปันช่วงเวลา Boss Raid การต่อสู้ ชัยชนะ ของรางวัล หรือความทรงจำกับปาร์ตี้หรือกิลด์","เขียนคำอธิบายสั้น ๆ เกี่ยวกับประสบการณ์และสิ่งที่คุณชื่นชอบใน PlayCrows V2","ตัวละครของคุณต้องมีเลเวล 60 ขึ้นไป","โพสต์ต้นฉบับต้องมีลิงก์เชิญ Discord ของ PlayCrows V2","หากโพสต์บน Facebook กรุณาแท็กเพจ Facebook อย่างเป็นทางการของ PlayCrows V2","แชร์หรือโปรโมตคอนเทนต์ใน 5 ชุมชนเกมที่แตกต่างกันและยังมีความเคลื่อนไหว โดยแนะนำชุมชน Night Crows หรือ MMORPG","ทั้ง 5 ชุมชนต้องเป็นชุมชนที่มีการใช้งานจริง กลุ่มที่ไม่มีความเคลื่อนไหว เป็นสแปม ไม่เกี่ยวข้อง หรือสร้างขึ้นเพื่อกิจกรรมจะไม่ได้รับการยอมรับ","โพสต์ต้นฉบับและโพสต์ในชุมชนทั้งหมดต้องเป็นสาธารณะและสามารถเข้าถึงได้","โพสต์ส่วนตัว ลิงก์ที่เข้าถึงไม่ได้ โพสต์ที่ถูกลบ ชุมชนซ้ำหรือไม่มีความเคลื่อนไหว และการส่งที่ไม่ถูกต้องจะไม่ได้รับการยอมรับ"],"description":"แบ่งปันพัฒนาการของตัวละคร ช่วงเวลาที่น่าจดจำ และฟีเจอร์ต่าง ๆ ของ PlayCrows V2 ที่คุณชื่นชอบ แสดงให้ผู้เล่นคนอื่นเห็นว่าคุณเริ่มต้นจากจุดไหนและเดินทางมาไกลแค่ไหนแล้ว","form_fields":[{"id":"field_en_1786794917915","type":"url","label":"ลิงก์โพสต์ PlayCrows V2 Journey","helpText":"Enter the direct link to your public Facebook, TikTok, or Instagram PlayCrows V2 Journey post.","maxItems":3,"minItems":3,"required":true,"placeholder":"https://…"},{"id":"field_en_1786794946905","type":"links","label":"ลิงก์ชุมชนเกมที่ใช้งานอยู่","helpText":"Submit the 5 links where you promoted your PlayCrows V2 Journey. All communities must be active.","maxItems":5,"minItems":5,"required":true,"placeholder":"https://…"}],"action_links":[],"require_player_id":true,"short_description":"คุณมาถึงเลเวล 60 แล้ว — ถึงเวลาที่จะแบ่งปันเส้นทาง PlayCrows V2 ของคุณให้กับชุมชน!","require_character_name":true},"zh-TW":{"title":"🎉我的 PLAYCROWS V2 旅程","rewards":["Draught of Vigilance (Bound) ×200","Superior Draught of Fury (Bound) ×20","Superior Draught of Overcoming (Bound) ×20","Superior Draught of Antagonism (Bound) ×20","Sealed Hero Weapon Selection Box (Attribution) ×1","Sealed Hero Accessory Selection Box (Attribution) ×1","Sealed Hero Armor Selection Box (Attribution) ×6","Sealed Hero Bracelet Selection Box (Attribution) ×1","Sealed Hero Epaulettes Selection Box (Attribution) ×1","Sealed Hero Trinket Selection Box (Attribution) ×5","sturdy bundle of yarn box (attributed) ×10","torn of invoices (attribution) ×50","torn seniority letter (attribution) ×50"],"mechanics":["製作介紹你的 PlayCrows V2 Journey 的內容。你可以在 Facebook、TikTok 或 Instagram 發布遊戲截圖、短影片，或兩者一起分享。","分享你喜歡的 PlayCrows V2 遊戲特色、系統或內容。","展示你的角色成長過程以及角色如何逐漸變得更強。","分享你幸運獲得神話坐騎或神話武器外觀的精彩時刻，並展示在 PlayCrows V2 中獲得它們的機會。","分享與隊伍或公會一起挑戰 Boss Raid 的戰鬥、勝利、掉落或其他難忘時刻。","簡單描述你的 PlayCrows V2 遊戲體驗以及你喜歡遊戲的原因。","角色必須達到 60 級或以上才能參加。","原始貼文中必須清楚包含 PlayCrows V2 Discord 邀請連結。","如果使用 Facebook 發布，請標記 PlayCrows V2 官方 Facebook 專頁。","將你的內容分享到 5 個不同且活躍的遊戲社群，建議選擇與 Night Crows 或 MMORPG 相關的社群。","5 個社群都必須是真實且活躍的社群。不活躍、已廢棄、垃圾廣告、無關或專門為活動建立的社群將不被接受。","原始內容以及所有社群貼文必須保持公開且可正常瀏覽，以便工作人員驗證。","私人貼文、無法瀏覽或已刪除的內容、重複或不活躍的社群，以及無效的提交將不被接受。"],"description":"分享你的角色成長、難忘的遊戲時刻，以及你最喜歡的 PlayCrows V2 遊戲內容。向其他玩家展示你從哪裡開始、角色成長了多少，以及你在 PlayCrows V2 中最精彩的經歷。","form_fields":[{"id":"field_en_1786794917915","type":"url","label":"PlayCrows V2 Journey 原始貼文連結","helpText":"Enter the direct link to your public Facebook, TikTok, or Instagram PlayCrows V2 Journey post.","maxItems":3,"minItems":3,"required":true,"placeholder":"https://…"},{"id":"field_en_1786794946905","type":"links","label":"活躍遊戲社群連結","helpText":"Submit the 5 links where you promoted your PlayCrows V2 Journey. All communities must be active.","maxItems":5,"minItems":5,"required":true,"placeholder":"https://…"}],"action_links":[],"require_player_id":true,"short_description":"你已經達到 60 級 — 現在是時候向大家分享你的 PlayCrows V2 冒險旅程了！","require_character_name":true}}$translations2$::jsonb,
